-- TEST ONLY synthetic800 metadata/canonical football, actual migrated SQL only.
-- This does NOT issue a genuine current-source/native/operator capability.
create function pg_temp.native800_sha(t text)returns text language sql immutable as $$select encode(sha256(convert_to(t,'UTF8')),'hex')$$;
create function pg_temp.native800_canonical(j jsonb)returns text language sql immutable as $$select private_fcf_future_import.canonical_json(j)$$;
create function pg_temp.native800_reject(command text,label text)returns void language plpgsql as $$begin begin execute command;raise exception 'NATIVE800 TEST: accepted %',label;exception when others then if sqlerrm like 'NATIVE800 TEST:%'then raise;end if;end;end$$;
-- Explicit old derived rows are beforeimage DATA, not an assertion of correctness.
insert into player_scores(round_id,player_id,points,computed_at)select(select id from rounds where competition_id=797 and number=3),(select id from players where competition_id=797 limit 1),42,'2026-10-01T12:00Z' on conflict(round_id,player_id)do update set points=excluded.points;
insert into player_scores(round_id,player_id,points,computed_at)select(select id from rounds where competition_id=783 and number=3),(select id from players where competition_id=783 limit 1),6.5,'2026-10-01T12:00Z' on conflict(round_id,player_id)do update set points=excluded.points;
do $$declare v jsonb;p jsonb;b jsonb;cap jsonb;mp jsonb;fs jsonb:='[]';f jsonb;policy private_historical_statistics.policies%rowtype;projection jsonb;scores jsonb;privacy_keys text[];stamp timestamptz:=clock_timestamp();begin
 select rollout into v from fcf_target_packets;p:=(v->>'targetPacketText')::jsonb;select *into policy from private_historical_statistics.policies where document->>'competitionSlug'='es-ct-tercera-g9'and document->>'sourcePolicy'='es-fcf-six-reviewed-history-v1';
 for f in select value from jsonb_array_elements(p#>'{target,fixtures}')loop
  f:=jsonb_set(f,'{source,capturedUTC}',to_jsonb(stamp-interval'2 minutes'));
  if f->>'statisticsStatus'='unavailable_historical'then
   f:=f||jsonb_build_object('policyId',policy.id,'policySha256',policy.policy_sha256);f:=jsonb_set(f,'{source,historicalObservation}',jsonb_build_object('kind','fcf-six-fresh-historical-observation','targetSlug','es-ct-tercera-g9','sourceMatchId',substring(f->>'id'from 3),'policyId',policy.id,'policySha256',policy.policy_sha256,'approvedOriginalSha256',f#>>'{source,rawSha256}','freshRawSha256',f#>>'{source,rawSha256}','fixture',f->'sourceFixture'));
  end if;fs:=fs||jsonb_build_array(f);
 end loop;
 cap:=jsonb_build_object('runId','90000001001','sourceCommit',repeat('a',40),'artifactId','90000001002','artifactDigest','sha256:'||repeat('a',64),'manifestSha256',repeat('b',64),'planSha256',repeat('c',64),'runtimeSha256',repeat('d',64),'newSourceGETs',240,'actualSourceGETs',541,'firstSourceUTC',stamp-interval'15 minutes','lastSourceEndedUTC',stamp-interval'2 minutes','sourceFreshUntil',stamp-interval'15 minutes'+interval'24 hours','sourceRefusal',false,'complete',true,'nativeAdmission',false,'activationEligible',false);
 b:=jsonb_build_object('schemaVersion',1,'kind','fcf-g9-native800-source','protocol','fcf-g9-native800-v1','targetSlug','es-ct-tercera-g9','calendarAuthority','full-report-derived-240-v1','sourceCommit',repeat('a',40),'sourceClaimState','consumed','maximumSourceGETs',800,'anchor','{"runId":"40851165521","actualSourceGETs":301,"sourceFreshUntil":"2026-10-29T18:09:27.203Z"}'::jsonb,'cleanupIssuerSourceCommit','da8516a66084926ebddd3f065fc90d85c2bdf9b9','currentCapture',cap,'policyHashes',jsonb_build_object('six',policy.policy_sha256),'firstSourceUTC',cap->'firstSourceUTC','sourceFreshUntil',cap->'sourceFreshUntil');
 b:=b||jsonb_build_object('sourceFingerprintSha256',pg_temp.native800_sha(pg_temp.native800_canonical(jsonb_build_object('targetSlug','es-ct-tercera-g9','currentCapture',cap,'policyHashes',b->'policyHashes','fixtures',fs))));
 select array_agg(distinct k order by k)into privacy_keys from(select public.anonimizacijski_kljuc((select country_id::text from competitions where id=797)||'|reg|'||(x->>'regSt'))k from jsonb_array_elements(fs)fixture_row(doc) cross join lateral jsonb_array_elements(case when fixture_row.doc->>'statisticsStatus'='available'then fixture_row.doc->'appearances'else '[]'::jsonb end)x union select public.anonimizacijski_kljuc((select country_id::text from competitions where id=797)||'|'||(x->>'ime'))from jsonb_array_elements(fs)fixture_row(doc) cross join lateral jsonb_array_elements(case when fixture_row.doc->>'statisticsStatus'='available'then fixture_row.doc->'appearances'else '[]'::jsonb end)x)keys;
 projection:=private_fcf_future_projection.capture('es-ct-tercera-g9',privacy_keys);scores:=jsonb_build_object('selectedG9',private_fcf_native800.score_state(797),'offTargetG1',private_fcf_native800.score_state(783));
 p:=(p-array['schemaVersion','kind','target','databaseInventory'])||jsonb_build_object('schemaVersion',1,'kind','fcf-native800-import-packet','protocol','fcf-native800-v1','captureSourceCommit',repeat('a',40),'auditedUTC',stamp,'databaseInventory',projection->'databaseInventory','target',((p->'target')-'firstFantasyPlayedOn')||jsonb_build_object('sourceEvidence',b,'sourceCode','4118349-4118588','historicalCutline','2026-10-24','fixtures',fs),'scoreBeforeimages',scores,'nativeSnapshotText',projection->>'dependencySnapshotText','nativeSnapshotSha256',projection->>'dependencySnapshotSha256');
 mp:=(v#>>'{identityPlan,mappingText}')::jsonb||jsonb_build_object('schemaVersion',1,'sourceCommit',v->>'sourceCommit','captureSourceCommit',repeat('a',40),'auditedUTC',stamp,'databaseSha256',repeat('e',64),'existingExceptionBindingsSha256',repeat('f',64),'sourceFingerprintSha256',b->>'sourceFingerprintSha256');
 v:=v||jsonb_build_object('schemaVersion',1,'kind','fcf-native800-import-rollout','protocol','fcf-native800-v1','targetPacketText',p::text,'targetPacketSha256',pg_temp.native800_sha(p::text),'inventoryBinding',b,'execution',jsonb_build_object('repository','Lovro-splichal-orhanizagi/mnzgorenjska','ref','refs/heads/main','commit',v->>'sourceCommit','runId','90000001003','runAttempt','1'),'identityPlan',jsonb_build_object('mappingText',mp::text,'mappingSha256',pg_temp.native800_sha(mp::text)),'scoreBeforeimages',scores,'nativeSnapshotText',projection->>'dependencySnapshotText','nativeSnapshotSha256',projection->>'dependencySnapshotSha256','readiness',null);
 update fcf_target_packets set rollout=v;
end$$;
create function pg_temp.native800_attest(v jsonb,stage text)returns text language sql as $$select jsonb_build_object('schemaVersion',1,'kind','fcf-native800-stage-attestation','stage',stage,'targetSlug','es-ct-tercera-g9','sourceCommit',v->>'sourceCommit','execution',v->'execution','rolloutSha256',pg_temp.native800_sha(v::text),'sourceBindingSha256',pg_temp.native800_sha(pg_temp.native800_canonical(v->'inventoryBinding')),'counter',jsonb_build_object('schemaVersion',1,'kind','fcf-refresh800-ledger','profileSha256','4b379dadb577fc0269dad744782faebb9c771fd3c7de13e492595fbac0584eeb','anchor',v#>'{inventoryBinding,anchor}','actualSourceGETs',541,'maximumCumulativeSourceGETs',800,'probeAttempts',1,'lastSourceEndedUTC',v#>'{inventoryBinding,currentCapture,lastSourceEndedUTC}','historySha256',repeat('f',64),'sourceRefusal',false,'verifiedUTC',clock_timestamp()))::text$$;
create function pg_temp.native800_import(v jsonb)returns jsonb language plpgsql as $$declare t text:=pg_temp.native800_attest(v,'import');begin return public.fcf_native800_import(v::text,pg_temp.native800_sha(v::text),t,pg_temp.native800_sha(t));end$$;
create function pg_temp.native800_mutant(v jsonb,key text,value jsonb)returns jsonb language plpgsql as $$declare p jsonb;begin p:=jsonb_set((v->>'targetPacketText')::jsonb,array[key],value);return jsonb_set(v,array[key],value)||jsonb_build_object('targetPacketText',p::text,'targetPacketSha256',pg_temp.native800_sha(p::text));end$$;
select pg_temp.native800_reject(format('select pg_temp.native800_import(%L::jsonb)',jsonb_set(rollout,'{inventoryBinding,protocol}','"six-reviewed-continuation-v1"')),'legacy retag')from fcf_target_packets;
select pg_temp.native800_reject(format('select pg_temp.native800_import(%L::jsonb)',pg_temp.native800_mutant(rollout,'scoreBeforeimages',jsonb_set(rollout->'scoreBeforeimages','{offTargetG1,snapshotText}','"[]"'))),'G1 beforeimage drift')from fcf_target_packets;
select pg_temp.native800_reject(format('select pg_temp.native800_import(%L::jsonb)',jsonb_set(rollout,'{execution,runAttempt}','"2"')),'attempt2')from fcf_target_packets;
select pg_temp.native800_reject('select public.fcf_native800_check(''{}'',''bad'',true,''{}'',''bad'')','activation true');
create temporary table native800_result as select pg_temp.native800_import(rollout)result from fcf_target_packets;
select case when result->>'stage'='imported'and not(select active from competitions where id=797)then 'FCF_NATIVE800_IMPORT_PASS'else 'FAIL'end from native800_result;
select case when pg_temp.native800_import(rollout)->>'noOp'='true'then 'FCF_NATIVE800_NOOP_PASS'else 'FAIL'end from fcf_target_packets;
select case when(public.fcf_native800_receipt('es-ct-tercera-g9'))->>'rolloutSha256'=pg_temp.native800_sha(rollout::text)then 'FCF_NATIVE800_READBACK_PASS'else 'FAIL'end from fcf_target_packets;
with attested as materialized(select rollout,pg_temp.native800_attest(rollout,'check')t from fcf_target_packets)select case when public.fcf_native800_check(rollout::text,pg_temp.native800_sha(rollout::text),false,t,pg_temp.native800_sha(t))->>'canonicalVerified'='true'then 'FCF_NATIVE800_CHECK_PASS'else 'FAIL'end from attested;
-- Freshness is source-stage metadata, never a client count-zero override.
with attested as materialized(select rollout,pg_temp.native800_attest(rollout,'import')::jsonb a from fcf_target_packets),bad as(select rollout,jsonb_set(a,'{counter,verifiedUTC}',to_jsonb(clock_timestamp()-interval'6 minutes'))::text t from attested)select pg_temp.native800_reject(format('select private_fcf_native800.stage_attestation(%L,%L,%L::jsonb,''import'',%L)',t,pg_temp.native800_sha(t),rollout::text,pg_temp.native800_sha(rollout::text)),'stale source-stage ledger')from bad;
with attested as materialized(select rollout,pg_temp.native800_attest(rollout,'import')::jsonb a from fcf_target_packets),bad as(select rollout,jsonb_set(a,'{counter,actualSourceGETs}','0')::text t from attested)select pg_temp.native800_reject(format('select private_fcf_native800.stage_attestation(%L,%L,%L::jsonb,''import'',%L)',t,pg_temp.native800_sha(t),rollout::text,pg_temp.native800_sha(rollout::text)),'caller zero')from bad;
savepoint native800_offtarget_mutant;
update player_scores set points=points+1 where round_id in(select id from rounds where competition_id=783);
select pg_temp.native800_reject('select public.fcf_native800_receipt(''es-ct-tercera-g9'')','unexpected G1 change after import');
rollback to savepoint native800_offtarget_mutant;
savepoint native800_rules_mutant;
do $$declare b text;d text;begin select prosrc,pg_get_functiondef(oid)into b,d from pg_proc where oid='public.recompute_round_scores(bigint)'::regprocedure;execute replace(d,b,b||E'\n-- TEST ONLY source mutation\n');end$$;
select pg_temp.native800_reject('select private_fcf_native800.scoring_guard()','scoring source mutation');
rollback to savepoint native800_rules_mutant;
select private_fcf_native800.scoring_guard();
select 'FCF_NATIVE800_NEGATIVES_PASS';
